import{_ as o,o as t,c as s,ag as r}from"./chunks/framework.BZohXCq9.js";const p=JSON.parse('{"title":"Phase 2: Student Dashboard – Complete Documentation","description":"","frontmatter":{},"headers":[],"relativePath":"02_STUDENT_DASHBOARD.md","filePath":"02_STUDENT_DASHBOARD.md"}'),d={name:"02_STUDENT_DASHBOARD.md"};function n(i,e,l,c,a,u){return t(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="phase-2-student-dashboard-–-complete-documentation" tabindex="-1">Phase 2: Student Dashboard – Complete Documentation <a class="header-anchor" href="#phase-2-student-dashboard-–-complete-documentation" aria-label="Permalink to &quot;Phase 2: Student Dashboard – Complete Documentation&quot;">​</a></h1><p>This document describes the <strong>Student Dashboard</strong> end-to-end: routes, layout, each major screen, the frontend files involved, the GraphQL operations used, and the backend resolvers/models behind them. Use it as the high-level map of the student area, then open the deep module docs under <code>docs/modules/student-dashboard/</code> for file-by-file detail.</p><hr><h2 id="_1-purpose-and-entry-point" tabindex="-1">1. Purpose and entry point <a class="header-anchor" href="#_1-purpose-and-entry-point" aria-label="Permalink to &quot;1. Purpose and entry point&quot;">​</a></h2><ul><li><strong>Purpose:</strong> The Student Dashboard is the student’s main workspace for discovering instructors, booking lessons, completing payments, tracking booked lessons, managing profile data, viewing payment history, tracking lesson progress, leaving reviews, and chatting with instructors.</li><li><strong>Entry:</strong> User signs in with an account that has <code>role: &quot;Student&quot;</code>. After sign-in, the app redirects into the student dashboard routes.</li><li><strong>Protection:</strong> All <code>/student-dashboard/*</code> routes are wrapped in <code>StudentPrivateRoute</code>, which ensures the user is authenticated and has the student role.</li></ul><hr><h2 id="_2-layout-and-routing" tabindex="-1">2. Layout and routing <a class="header-anchor" href="#_2-layout-and-routing" aria-label="Permalink to &quot;2. Layout and routing&quot;">​</a></h2><h3 id="_2-1-how-the-student-area-is-mounted" tabindex="-1">2.1 How the student area is mounted <a class="header-anchor" href="#_2-1-how-the-student-area-is-mounted" aria-label="Permalink to &quot;2.1 How the student area is mounted&quot;">​</a></h3><ul><li><strong>Route definition:</strong> <code>Frontend/src/routes/index.tsx</code><ul><li>Base path: <code>/student-dashboard</code></li><li>Wrapper element: <code>StudentRoutes</code></li></ul></li><li><strong>Route wrapper:</strong> <code>Frontend/src/routes/StudentRoutes.tsx</code><ul><li>Applies student-only route protection and layout composition.</li></ul></li><li><strong>Layout:</strong> <code>Frontend/src/layouts/StudentLayout.tsx</code><ul><li>Renders sidebar, top navigation, and the active student page.</li><li>Integrates booking/chat badge behavior through shared hooks and Redux/socket state.</li></ul></li><li><strong>Shared shell pieces:</strong><ul><li><code>Frontend/src/components/common/SideBar.tsx</code></li><li><code>Frontend/src/components/common/DashNavBar.tsx</code></li><li><code>Frontend/src/utils/useBookingNotification.ts</code></li><li><code>Frontend/src/hooks/useSockets.ts</code></li><li><code>Frontend/src/utils/socket.ts</code></li><li><code>Frontend/src/store/slices/chatSlice.ts</code></li></ul></li></ul><h3 id="_2-2-student-routes" tabindex="-1">2.2 Student routes <a class="header-anchor" href="#_2-2-student-routes" aria-label="Permalink to &quot;2.2 Student routes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Screen</th><th>Path</th></tr></thead><tbody><tr><td>Overview</td><td><code>/student-dashboard/overview</code></td></tr><tr><td>Settings</td><td><code>/student-dashboard/settings</code></td></tr><tr><td>Edit profile</td><td><code>/student-dashboard/settings/edit-profile</code></td></tr><tr><td>Booked lessons</td><td><code>/student-dashboard/book</code></td></tr><tr><td>Search instructors</td><td><code>/student-dashboard/search</code></td></tr><tr><td>Instructor detail</td><td><code>/student-dashboard/search/instructors/:id</code></td></tr><tr><td>Booking details</td><td><code>/student-dashboard/booking-details</code></td></tr><tr><td>Complete payment</td><td><code>/student-dashboard/complete-payment</code></td></tr><tr><td>Help &amp; support</td><td><code>/student-dashboard/help-support</code></td></tr><tr><td>Payment history</td><td><code>/student-dashboard/payment-history</code></td></tr><tr><td>Progress tracking</td><td><code>/student-dashboard/reviews</code></td></tr><tr><td>Feedback &amp; rating</td><td><code>/student-dashboard/Feedback</code></td></tr><tr><td>Review form</td><td><code>/student-dashboard/review-form</code></td></tr><tr><td>Review display</td><td><code>/student-dashboard/review-display</code></td></tr><tr><td>All booking slots</td><td><code>/student-dashboard/allBookingSlots</code></td></tr><tr><td>Chat</td><td><code>/student-dashboard/chat</code></td></tr></tbody></table><hr><h2 id="_3-screen-by-screen-breakdown" tabindex="-1">3. Screen-by-screen breakdown <a class="header-anchor" href="#_3-screen-by-screen-breakdown" aria-label="Permalink to &quot;3. Screen-by-screen breakdown&quot;">​</a></h2><p>Each section below lists the <strong>route</strong>, <strong>main frontend files</strong>, <strong>what the screen does</strong>, <strong>GraphQL operations</strong>, and <strong>backend modules</strong> involved.</p><hr><h3 id="_3-1-overview" tabindex="-1">3.1 Overview <a class="header-anchor" href="#_3-1-overview" aria-label="Permalink to &quot;3.1 Overview&quot;">​</a></h3><ul><li><strong>Route:</strong> <code>/student-dashboard/overview</code></li><li><strong>Primary page:</strong> <code>Frontend/src/pages/private/student-dashboard/studentOverview.tsx</code></li><li><strong>What it does:</strong> Shows top-level student stats, a lesson list/history block, and notes/feedback from instructors. Provides a CTA to search for instructors.</li><li><strong>Frontend files:</strong><ul><li><code>Frontend/src/pages/private/student-dashboard/studentOverview.tsx</code></li><li><code>Frontend/src/components/StudentComponents/StudentDashboard/LoadingCard.tsx</code></li><li><code>Frontend/src/components/StudentComponents/StudentDashboard/CircularProgressDashboard.tsx</code></li><li><code>Frontend/src/components/StudentComponents/StudentDashboard/FeedBackModal.tsx</code></li></ul></li><li><strong>Frontend GraphQL:</strong><ul><li><code>GET_STUDENT_DASHBOARD_STATS</code></li><li><code>GET_STUDENT_LESSONS</code></li><li><code>GET_STUDENT_FEEDBACKS</code></li><li>File: <code>Frontend/src/graphql/Queries/StudentDashboard.ts</code></li></ul></li><li><strong>Backend:</strong><ul><li>TypeDefs: <code>server/src/graphql/typeDefs/studentDashboard.js</code></li><li>Resolvers: <code>server/src/graphql/resolvers/studentDashboard.resolver.js</code></li><li>Models: <code>server/src/models/studentBooking.model.js</code>, <code>server/src/models/User.js</code>, <code>server/src/models/LessonFeedBack.js</code></li></ul></li><li><strong>Deep doc:</strong> <code>docs/modules/student-dashboard/overview-analytics.md</code></li></ul><hr><h3 id="_3-2-search-instructors" tabindex="-1">3.2 Search Instructors <a class="header-anchor" href="#_3-2-search-instructors" aria-label="Permalink to &quot;3.2 Search Instructors&quot;">​</a></h3><ul><li><strong>Routes:</strong> <code>/student-dashboard/search</code>, <code>/student-dashboard/search/instructors/:id</code></li><li><strong>Primary pages/components:</strong><ul><li><code>Frontend/src/pages/private/student-dashboard/searchInstructor.tsx</code></li><li><code>Frontend/src/components/ProfessionalInstructor/InstructorInfo.tsx</code></li><li><code>Frontend/src/pages/public/OurInstructor.tsx</code></li><li><code>Frontend/src/components/InstructorComponent/PostSummary.tsx</code></li></ul></li><li><strong>What it does:</strong> Lets the student browse/filter instructors, see location/map context, open a specific instructor, inspect availability/packages/reviews, and start booking.</li><li><strong>Frontend files:</strong><ul><li><code>Frontend/src/components/FilterPopover.tsx</code></li><li><code>Frontend/src/components/AddressSearch.tsx</code></li><li><code>Frontend/src/components/InstructorComponent/Availability.tsx</code></li><li><code>Frontend/src/components/InstructorComponent/Summary.tsx</code></li><li><code>Frontend/src/components/InstructorComponent/BulkPackageCard.tsx</code></li><li><code>Frontend/src/components/StudentComponents/InstructorReviews.tsx</code></li></ul></li><li><strong>Frontend GraphQL:</strong><ul><li>Instructor public/discovery queries from <code>Frontend/src/graphql/mutations/instructorPublic.ts</code></li><li>Review queries from <code>Frontend/src/graphql/Queries/ReviewQueries.ts</code></li></ul></li><li><strong>Backend:</strong><ul><li>TypeDefs: <code>server/src/graphql/typeDefs/instructorPublic.typeDefs.js</code>, <code>server/src/graphql/typeDefs/ReviewTypes.js</code></li><li>Resolvers: <code>server/src/graphql/resolvers/instructorPublic.resolver.js</code>, <code>server/src/graphql/resolvers/Review.resolver.js</code></li><li>Models: <code>server/src/models/User.js</code>, <code>server/src/models/teacherTariff.model.js</code>, <code>server/src/models/teacherAvailability.model.js</code>, <code>server/src/models/Reviews.js</code></li></ul></li><li><strong>Deep doc:</strong> <code>docs/modules/student-dashboard/search-instructors.md</code></li></ul><hr><h3 id="_3-3-booked-lessons" tabindex="-1">3.3 Booked Lessons <a class="header-anchor" href="#_3-3-booked-lessons" aria-label="Permalink to &quot;3.3 Booked Lessons&quot;">​</a></h3><ul><li><strong>Routes:</strong> <code>/student-dashboard/book</code>, <code>/student-dashboard/booking-details</code>, <code>/student-dashboard/complete-payment</code></li><li><strong>Primary files:</strong><ul><li><code>Frontend/src/pages/private/student-dashboard/bookLesson.tsx</code></li><li><code>Frontend/src/pages/private/student-dashboard/bookingDetails.tsx</code></li><li><code>Frontend/src/pages/private/student-dashboard/CompletePaymentPage.tsx</code></li><li><code>Frontend/src/components/BookingList.tsx</code></li></ul></li><li><strong>What it does:</strong> Shows booked lessons with tab-based filtering, abandoned checkout recovery, later payment/T-48/3DS completion, booking details, cancellation, and refund request actions.</li><li><strong>Frontend GraphQL:</strong><ul><li><code>GET_STUDENT_BOOKINGS</code></li><li><code>CREATE_BOOKING_CHECKOUT_SESSION</code></li><li><code>CREATE_CHECKOUT_SESSION_FOR_PENDING_BOOKING</code></li><li><code>COMPLETE_BOOKING_FROM_CHECKOUT</code></li><li><code>COMPLETE_DEFERRED_BOOKING_FROM_CHECKOUT</code></li><li><code>COMPLETE_BOOKING_AFTER_PAYMENT</code></li><li><code>GET_T48_CLIENT_SECRET</code></li><li><code>COMPLETE_T48_SLOT_PAYMENT</code></li><li><code>CANCEL_BOOKING</code></li><li><code>REQUEST_REFUND</code></li><li>Files: <ul><li><code>Frontend/src/graphql/mutations/studentBooking.ts</code></li><li><code>Frontend/src/graphql/mutations/refundRequest.ts</code></li></ul></li></ul></li><li><strong>Backend:</strong><ul><li>TypeDefs: <code>server/src/graphql/typeDefs/studentBooking.typeDefs.js</code>, <code>server/src/graphql/typeDefs/refundRequest.typeDefs.js</code></li><li>Resolvers: <code>server/src/graphql/resolvers/studentBooking.resolver.js</code>, <code>server/src/graphql/resolvers/refundRequest.resolver.js</code></li><li>Services/jobs/routes: <ul><li><code>server/src/services/stripeService.js</code></li><li><code>server/src/services/transactionService.js</code></li><li><code>server/src/jobs/pendingBookingCleanupJob.js</code></li><li><code>server/src/jobs/t48ChargeJob.js</code></li><li><code>server/src/jobs/payoutJob.js</code></li><li><code>server/src/routes/stripeWebhook.routes.js</code></li></ul></li></ul></li><li><strong>Deep doc:</strong> <code>docs/modules/student-dashboard/booked-lessons.md</code></li></ul><hr><h3 id="_3-4-profile-setting" tabindex="-1">3.4 Profile Setting <a class="header-anchor" href="#_3-4-profile-setting" aria-label="Permalink to &quot;3.4 Profile Setting&quot;">​</a></h3><ul><li><strong>Routes:</strong> <code>/student-dashboard/settings</code>, <code>/student-dashboard/settings/edit-profile</code></li><li><strong>Primary files:</strong><ul><li><code>Frontend/src/pages/private/student-dashboard/profileSetting.tsx</code></li><li><code>Frontend/src/pages/private/student-dashboard/EditStudentProfile.tsx</code></li></ul></li><li><strong>What it does:</strong> Shows student profile info, profile image, language/address/personal details, and supports profile editing with upload/address suggestion flows.</li><li><strong>Frontend GraphQL:</strong><ul><li><code>GET_STUDENT_PROFILE</code></li><li><code>UPDATE_STUDENT_PROFILE</code></li><li>File: <code>Frontend/src/graphql/mutations/studentProfile.ts</code></li></ul></li><li><strong>Backend:</strong><ul><li>TypeDefs: <code>server/src/graphql/typeDefs.js</code>, <code>server/src/graphql/typeDefs/student.typeDefs.js</code></li><li>Resolvers: <code>server/src/graphql/resolvers.js</code>, <code>server/src/graphql/resolvers/student.resolver.js</code></li><li>Validation: <code>server/src/schemas/validation.js</code></li><li>Model: <code>server/src/models/User.js</code></li></ul></li><li><strong>Deep doc:</strong> <code>docs/modules/student-dashboard/profile-setting.md</code></li></ul><hr><h3 id="_3-5-help-support" tabindex="-1">3.5 Help &amp; Support <a class="header-anchor" href="#_3-5-help-support" aria-label="Permalink to &quot;3.5 Help &amp; Support&quot;">​</a></h3><ul><li><strong>Route:</strong> <code>/student-dashboard/help-support</code></li><li><strong>Primary page:</strong> <code>Frontend/src/pages/private/teacher-dashboard/HelpSuportPage.tsx</code> (shared with teacher-side support UI)</li><li><strong>What it does:</strong> Shows FAQs and a contact form for support inquiries.</li><li><strong>Frontend files:</strong><ul><li><code>Frontend/src/components/InstructorComponent/Help&amp;Support/TabPanel.tsx</code></li><li><code>Frontend/src/components/InstructorComponent/Help&amp;Support/FaqList.tsx</code></li><li><code>Frontend/src/components/InstructorComponent/Help&amp;Support/ContactSection.tsx</code></li><li><code>Frontend/src/components/InstructorComponent/Help&amp;Support/ContactForm.tsx</code></li><li><code>Frontend/src/hooks/UseFaqs&#39;s.ts</code></li></ul></li><li><strong>Frontend GraphQL:</strong><ul><li><code>GET_ALL_FAQS</code> from <code>Frontend/src/graphql/Queries/Faqs.ts</code></li><li><code>SEND_CONTACT_EMAIL</code> from <code>Frontend/src/graphql/mutations/AdminContact.ts</code></li></ul></li><li><strong>Backend:</strong><ul><li>TypeDefs: <code>server/src/graphql/typeDefs/Faq&#39;sTypes.js</code>, <code>server/src/graphql/typeDefs/AdminContactTypes.js</code></li><li>Resolvers: <code>server/src/graphql/resolvers/Faqs.resolver.js</code>, <code>server/src/graphql/resolvers/ContactDetail.resolver.js</code></li><li>Models/services: <code>FAQ&#39;s</code>, <code>AdminContact</code>, FAQ/contact service files</li></ul></li><li><strong>Deep doc:</strong> <code>docs/modules/student-dashboard/help-support.md</code></li></ul><hr><h3 id="_3-6-payment-history" tabindex="-1">3.6 Payment History <a class="header-anchor" href="#_3-6-payment-history" aria-label="Permalink to &quot;3.6 Payment History&quot;">​</a></h3><ul><li><strong>Route:</strong> <code>/student-dashboard/payment-history</code></li><li><strong>Primary page:</strong> <code>Frontend/src/pages/private/student-dashboard/StudentPaymentHistoryPage.tsx</code></li><li><strong>What it does:</strong> Shows payment/refund ledger rows, summary cards, tab filters, pagination, and transaction details.</li><li><strong>Frontend GraphQL:</strong><ul><li><code>GET_STUDENT_TRANSACTIONS</code></li><li><code>GET_STUDENT_TRANSACTIONS_COUNT</code></li><li><code>GET_STUDENT_TRANSACTION_STATS</code></li><li>File: <code>Frontend/src/graphql/Queries/transactionQueries.ts</code></li></ul></li><li><strong>Backend:</strong><ul><li>TypeDefs: <code>server/src/graphql/typeDefs/transaction.typeDefs.js</code>, <code>server/src/graphql/typeDefs/refundRequest.typeDefs.js</code></li><li>Resolvers: <code>server/src/graphql/resolvers/transaction.resolver.js</code>, <code>server/src/graphql/resolvers/refundRequest.resolver.js</code></li><li>Models: <code>transaction.model.js</code>, <code>refundRequest.model.js</code>, <code>studentBooking.model.js</code></li></ul></li><li><strong>Deep doc:</strong> <code>docs/modules/student-dashboard/payment-history.md</code></li></ul><hr><h3 id="_3-7-progress-tracking" tabindex="-1">3.7 Progress Tracking <a class="header-anchor" href="#_3-7-progress-tracking" aria-label="Permalink to &quot;3.7 Progress Tracking&quot;">​</a></h3><ul><li><strong>Routes:</strong> <code>/student-dashboard/reviews</code>, <code>/student-dashboard/allBookingSlots</code></li><li><strong>Primary page/component:</strong> <code>Frontend/src/components/StudentComponents/ReviewTab/Dashboard.tsx</code></li><li><strong>What it does:</strong> Shows completed/remaining lesson hours, days since last lesson, and a booking-slot table that connects to review/feedback actions.</li><li><strong>Frontend files:</strong><ul><li><code>Frontend/src/components/StudentComponents/ReviewTab/StudentHourPercentage.tsx</code></li><li><code>Frontend/src/components/StudentComponents/ReviewTab/BookingSlotTable.tsx</code></li><li><code>Frontend/src/components/StudentComponents/ReviewTab/AllBookingSlotPage.tsx</code></li><li><code>Frontend/src/hooks/ReviewSystem.ts</code></li><li><code>Frontend/src/hooks/UseReview.ts</code></li><li><code>Frontend/src/hooks/UseStudentHourProgress.ts</code></li></ul></li><li><strong>Frontend GraphQL:</strong><ul><li><code>GET_STUDENT_HOURS_PROGRESS</code></li><li><code>GET_ALL_STUDENT_BOOKING_SLOTS</code></li><li>File: <code>Frontend/src/graphql/Queries/ReviewQueries.ts</code></li></ul></li><li><strong>Backend:</strong><ul><li>TypeDefs: <code>server/src/graphql/typeDefs/student.typeDefs.js</code>, <code>server/src/graphql/typeDefs/ReviewTypes.js</code></li><li>Resolvers: <code>server/src/graphql/resolvers/student.resolver.js</code>, <code>server/src/graphql/resolvers/Review.resolver.js</code>, <code>server/src/graphql/resolvers/studentDashboard.resolver.js</code></li><li>Models: <code>User.js</code>, <code>studentBooking.model.js</code>, <code>Reviews.js</code></li></ul></li><li><strong>Deep doc:</strong> <code>docs/modules/student-dashboard/progress-tracking.md</code></li></ul><hr><h3 id="_3-8-feedback-rating" tabindex="-1">3.8 Feedback &amp; Rating <a class="header-anchor" href="#_3-8-feedback-rating" aria-label="Permalink to &quot;3.8 Feedback &amp; Rating&quot;">​</a></h3><ul><li><strong>Routes:</strong> <code>/student-dashboard/Feedback</code>, <code>/student-dashboard/review-form</code>, <code>/student-dashboard/review-display</code></li><li><strong>Primary files:</strong><ul><li><code>Frontend/src/components/StudentComponents/ReviewTab/OnlyReviewsTab.tsx</code></li><li><code>Frontend/src/components/StudentComponents/ReviewTab/ReviewForm.tsx</code></li><li><code>Frontend/src/components/StudentComponents/ReviewTab/ReviewDisplay.tsx</code></li></ul></li><li><strong>What it does:</strong> Lets students leave ratings/reviews for instructors per lesson slot, view existing reviews, edit them, or delete them.</li><li><strong>Frontend GraphQL:</strong><ul><li><code>GET_ALL_STUDENT_BOOKING_SLOTS</code></li><li><code>GET_REVIEW_BY_LESSON_SLOT</code></li><li><code>GET_STUDENT_REVIEWS</code></li><li><code>CREATE_REVIEW</code></li><li><code>UPDATE_REVIEW</code></li><li><code>DELETE_REVIEW</code></li><li>File: <code>Frontend/src/graphql/Queries/ReviewQueries.ts</code></li></ul></li><li><strong>Backend:</strong><ul><li>TypeDefs: <code>server/src/graphql/typeDefs/ReviewTypes.js</code></li><li>Resolvers: <code>server/src/graphql/resolvers/Review.resolver.js</code></li><li>Models: <code>server/src/models/Reviews.js</code>, <code>server/src/models/studentBooking.model.js</code>, <code>server/src/models/User.js</code></li></ul></li><li><strong>Deep doc:</strong> <code>docs/modules/student-dashboard/feedback-rating.md</code></li></ul><hr><h3 id="_3-9-messages-chat" tabindex="-1">3.9 Messages / Chat <a class="header-anchor" href="#_3-9-messages-chat" aria-label="Permalink to &quot;3.9 Messages / Chat&quot;">​</a></h3><ul><li><strong>Route:</strong> <code>/student-dashboard/chat</code></li><li><strong>Primary page:</strong> <code>Frontend/src/pages/private/student-dashboard/chat/index.tsx</code></li><li><strong>What it does:</strong> Lets students message instructors with message history, real-time updates, unread handling, typing behavior, and shared chat UI.</li><li><strong>Frontend files:</strong><ul><li><code>Frontend/src/components/Chat/ChatList.tsx</code></li><li><code>Frontend/src/components/Chat/ChatWindow.tsx</code></li><li><code>Frontend/src/components/Chat/MessageItem.tsx</code></li><li><code>Frontend/src/store/slices/chatSlice.ts</code></li><li><code>Frontend/src/utils/socket.ts</code></li></ul></li><li><strong>Frontend GraphQL:</strong><ul><li><code>GET_MESSAGES</code></li><li><code>SEND_MESSAGE</code></li><li><code>NEW_MESSAGE_SUBSCRIPTION</code></li><li>File: <code>Frontend/src/graphql/Queries/Chat.ts</code></li></ul></li><li><strong>Backend:</strong><ul><li>TypeDefs: <code>server/src/graphql/typeDefs/chat.typeDefs.js</code></li><li>Resolvers: <code>server/src/graphql/resolvers/chat.resolvers.js</code></li><li>Real-time transport: <code>server/src/socket/index.js</code></li><li>Models: <code>Message.js</code>, <code>Conversation.js</code>, booking-derived instructor relationship data</li></ul></li><li><strong>Deep doc:</strong> <code>docs/modules/student-dashboard/messages-chat.md</code></li></ul><hr><h2 id="_4-shared-backend-modules-used-across-the-student-dashboard" tabindex="-1">4. Shared backend modules used across the student dashboard <a class="header-anchor" href="#_4-shared-backend-modules-used-across-the-student-dashboard" aria-label="Permalink to &quot;4. Shared backend modules used across the student dashboard&quot;">​</a></h2><p>These backend modules are reused by multiple student pages:</p><table tabindex="0"><thead><tr><th>Backend file</th><th>Why it matters</th></tr></thead><tbody><tr><td><code>server/src/graphql/resolvers/studentBooking.resolver.js</code></td><td>Central booking/payment/cancel/T-48 logic</td></tr><tr><td><code>server/src/graphql/resolvers/transaction.resolver.js</code></td><td>Student payment history and transaction stats</td></tr><tr><td><code>server/src/graphql/resolvers/refundRequest.resolver.js</code></td><td>Refund request creation and approval/rejection rules</td></tr><tr><td><code>server/src/services/stripeService.js</code></td><td>Checkout, PaymentIntent, refunds, transfers, payouts, commission split</td></tr><tr><td><code>server/src/jobs/t48ChargeJob.js</code></td><td>Deferred booking charge job</td></tr><tr><td><code>server/src/routes/stripeWebhook.routes.js</code></td><td>Stripe event completion and later-payment transitions</td></tr><tr><td><code>server/src/models/studentBooking.model.js</code></td><td>Main booking record used almost everywhere on the student side</td></tr><tr><td><code>server/src/models/User.js</code></td><td>Student/instructor profile data, hour tracking, payment-related fields</td></tr></tbody></table><hr><h2 id="_5-deep-module-docs" tabindex="-1">5. Deep module docs <a class="header-anchor" href="#_5-deep-module-docs" aria-label="Permalink to &quot;5. Deep module docs&quot;">​</a></h2><p>If you need file-by-file detail for one student feature, open the deep docs:</p><ul><li><code>docs/modules/student-dashboard/README.md</code></li><li><code>docs/modules/student-dashboard/overview-analytics.md</code></li><li><code>docs/modules/student-dashboard/search-instructors.md</code></li><li><code>docs/modules/student-dashboard/booked-lessons.md</code></li><li><code>docs/modules/student-dashboard/profile-setting.md</code></li><li><code>docs/modules/student-dashboard/help-support.md</code></li><li><code>docs/modules/student-dashboard/payment-history.md</code></li><li><code>docs/modules/student-dashboard/progress-tracking.md</code></li><li><code>docs/modules/student-dashboard/feedback-rating.md</code></li><li><code>docs/modules/student-dashboard/messages-chat.md</code></li></ul><hr><h2 id="_6-quick-developer-notes" tabindex="-1">6. Quick developer notes <a class="header-anchor" href="#_6-quick-developer-notes" aria-label="Permalink to &quot;6. Quick developer notes&quot;">​</a></h2><ul><li>The student dashboard mixes route-based screens with shared component systems reused by teacher/public flows; when changing those shared files, check other dashboards too.</li><li>Booking and payment logic is the most business-rule-heavy area; when debugging student issues, start with <code>studentBooking.resolver.js</code>, <code>refundRequest.resolver.js</code>, Stripe services/jobs, and the student booking/payment UI.</li><li>Progress tracking and feedback/rating are related but not identical: <ul><li>progress tracking = lesson hour/status visibility</li><li>feedback/rating = student reviews for instructors</li></ul></li><li>The top-level student phase doc is the high-level map; the deep module docs are the detailed implementation reference.</li></ul>',52)])])}const g=o(d,[["render",n]]);export{p as __pageData,g as default};
